async function runAnalysis() {
  // Define Kilauea summit location
  const kilauea = ee.Geometry.Point([-155.287, 19.421]);

  // Define search area (10 km radius to check for plume extension)
  const searchArea = kilauea.buffer(10000);

  // Hawaii local time July 20, 2025 10:44 am = UTC July 20, 2025 20:44
  const targetDate = '2025-07-20';
  const startDate = '2025-07-20';
  const endDate = '2025-07-21';

  console.log("Searching for imagery on:", targetDate);
  console.log("Location: Kilauea summit, Hawaii");

  // Try Sentinel-2 first (better resolution for plume detection)
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_HARMONIZED')
    .filterBounds(kilauea)
    .filterDate(startDate, endDate);

  const s2Count = s2Collection.size().getInfo();
  console.log("Sentinel-2 images found:", s2Count);

  // Try Landsat 9 as fallback
  const l9Collection = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2')
    .filterBounds(kilauea)
    .filterDate(startDate, endDate);

  const l9Count = l9Collection.size().getInfo();
  console.log("Landsat-9 images found:", l9Count);

  // Try Landsat 8 as additional fallback
  const l8Collection = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(kilauea)
    .filterDate(startDate, endDate);

  const l8Count = l8Collection.size().getInfo();
  console.log("Landsat-8 images found:", l8Count);

  // Check if any data exists
  if (s2Count === 0 && l9Count === 0 && l8Count === 0) {
    console.log("No satellite imagery available for future date: July 20, 2025");
